136	      Overwrite<TParams['_config']['$types']['ctx'], TParams['_ctx_out']>
137	    >;
138	    type: ProcedureType;
139	    path: string;
140	    input: TParams['_input_out'];
141	    rawInput: unknown;
142	    meta: TParams['_meta'] | undefined;
143	    next: {
144	      (): Promise<MiddlewareResult<TParams>>;
145	      <$Context>(opts: { ctx: $Context }): Promise<
146	        MiddlewareResult<{
147	          _config: TParams['_config'];
148	          _ctx_out: $Context;
149	          _input_in: TParams['_input_in'];
150	          _input_out: TParams['_input_out'];
151	          _output_in: TParams['_output_in'];
152	          _output_out: TParams['_output_out'];
153	          _meta: TParams['_meta'];
154	        }>
155	      >;
156	      (opts: { rawInput: unknown }): Promise<MiddlewareResult<TParams>>;
157	    };
158	  }): Promise<MiddlewareResult<TParamsAfter>>;
159	  _type?: string | undefined;
160	};
