200	export const experimental_standaloneMiddleware = <
201	  TCtx extends {
202	    ctx?: object;
203	    meta?: object;
204	    input?: unknown;
205	  },
206	>() => ({
207	  create: createMiddlewareFactory<
208	    RootConfig<{
209	      ctx: TCtx extends { ctx: infer T extends object } ? T : object;
210	      meta: TCtx extends { meta: infer T extends object } ? T : object;
211	      errorShape: object;
212	      transformer: object;
213	    }>,
214	    TCtx extends { input: infer T } ? T : unknown
215	  >(),
216	});
217	
218	function isPlainObject(obj: unknown) {
219	  return obj && typeof obj === 'object' && !Array.isArray(obj);
220	}
221	
222	/**
223	 * @internal
224	 * Please note, `trpc-openapi` uses this function.
225	 */
226	export function createInputMiddleware<TInput>(parse: ParseFn<TInput>) {
227	  const inputMiddleware: ProcedureBuilderMiddleware = async ({
228	    next,
229	    rawInput,
230	    input,
231	  }) => {
232	    let parsedInput: ReturnType<typeof parse>;
233	    try {
234	      parsedInput = await parse(rawInput);
235	    } catch (cause) {
236	      throw new TRPCError({
237	        code: 'BAD_REQUEST',
238	        cause,
239	      });
240	    }
241	
242	    // Multiple input parsers
243	    const combinedInput =
244	      isPlainObject(input) && isPlainObject(parsedInput)
245	        ? {
246	            ...input,
247	            ...parsedInput,
248	          }
249	        : parsedInput;
250	
251	    // TODO fix this typing?
252	    return next({ input: combinedInput } as any);
253	  };
254	  inputMiddleware._type = 'input';
255	  return inputMiddleware;
256	}
257	
258	/**
259	 * @internal
260	 */
261	export function createOutputMiddleware<TOutput>(parse: ParseFn<TOutput>) {
262	  const outputMiddleware: ProcedureBuilderMiddleware = async ({ next }) => {
263	    const result = await next();
264	    if (!result.ok) {
265	      // pass through failures without validating
266	      return result;
267	    }
268	    try {
269	      const data = await parse(result.data);
270	      return {
271	        ...result,
272	        data,
273	      };
274	    } catch (cause) {
275	      throw new TRPCError({
276	        message: 'Output validation failed',
277	        code: 'INTERNAL_SERVER_ERROR',
278	        cause,
279	      });
280	    }
281	  };
282	  outputMiddleware._type = 'output';
283	  return outputMiddleware;
284	}
