import { inferRouterInputs, inferRouterOutputs, initTRPC } from '@trpc/server';
import { Overwrite } from '@trpc/server/core/internals/utils';
import { createTRPCProxyClient } from '@trpc/client';
import { z } from 'zod';

type Equal<A, B> = (<T>() => T extends A ? 1 : 2) extends (<T>() => T extends B ? 1 : 2) ? true : false;
type Expect<T extends true> = T;
type Show<T> = { [K in keyof T]: T[K] } & {};

// ---- direct Overwrite probes
type P1 = Overwrite<string, string>;
export const p1: Expect<Equal<P1, string>> = true;
type P2 = Overwrite<string[], string[]>;
export const p2: Expect<Equal<P2, string[]>> = true;
type P3 = Overwrite<[string, number], [string, number]>;
export const p3: Expect<Equal<P3, [string, number]>> = true;
type Brand = string & { __brand: 'X' };
type P4 = Overwrite<Brand, Brand>;
export const p4: Expect<Equal<P4, Brand>> = true;
type P5 = Overwrite<string, never>;
export const p5: Expect<Equal<P5, never>> = true;
type P6 = Overwrite<{ a: string } | undefined, { a: string } | undefined>;
export const p6: Expect<Equal<P6, { a: string } | undefined>> = true;
type P7 = Overwrite<{ a: string }, any>;
export const p7: Expect<Equal<P7, any>> = true;
type P8 = Overwrite<Date, Date>;
export const p8: Expect<Equal<P8, Date>> = true;
type P9 = Overwrite<Map<string, number>, Map<string, number>>;
export const p9: Expect<Equal<P9, Map<string, number>>> = true;
type P10 = Overwrite<{ a: string }, { b: number }>;
export const p10: Expect<Equal<Show<P10>, { a: string; b: number }>> = true;
type P11 = Overwrite<unknown, unknown>;
export const p11: Expect<Equal<P11, unknown>> = true;
type P12 = Overwrite<readonly string[], readonly string[]>;
export const p12: Expect<Equal<P12, readonly string[]>> = true;
type P13 = Overwrite<{ a: string }, null>;
export const p13: Expect<Equal<P13, null>> = true;
type P14 = Overwrite<{ a: string } | null, { a: string } | null>;
export const p14: Expect<Equal<P14, { a: string } | null>> = true;
type P15 = Overwrite<any, { a: string }>;
export const p15: Expect<Equal<P15, { a: string }>> = true;
type P16 = Overwrite<{ a: string }, undefined>;
export const p16: Expect<Equal<P16, undefined>> = true;
type P17 = Overwrite<{ a: string }, {}>;
export const p17: Expect<Equal<Show<P17>, { a: string }>> = true;
type P18 = Overwrite<() => void, () => void>;
export const p18: Expect<Equal<P18, () => void>> = true;

// ---- end to end
const t = initTRPC.create();
const mw = t.middleware((opts) => opts.next());
const appRouter = t.router({
  str: t.procedure.input(z.string()).use(mw).query(({ input }) => input),
  arr: t.procedure.input(z.array(z.string())).use(mw).query(({ input }) => input),
  tuple: t.procedure.input(z.tuple([z.string(), z.number()])).use(mw).query(({ input }) => input),
  brand: t.procedure.input(z.string().brand('X')).use(mw).query(({ input }) => input),
  optObj: t.procedure.input(z.object({ a: z.string() }).optional()).use(mw).query(({ input }) => input),
  optStr: t.procedure.input(z.string().optional()).use(mw).query(({ input }) => input),
  date: t.procedure.input(z.date()).use(mw).query(({ input }) => input),
  set: t.procedure.input(z.set(z.string())).use(mw).query(({ input }) => input),
  rec: t.procedure.input(z.record(z.number())).use(mw).query(({ input }) => input),
